import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        String next() throws IOException {
            StringBuilder sb = new StringBuilder();
            int c;
            do {
                c = read();
                if (c == -1) return null;
            } while (Character.isWhitespace(c));
            while (c != -1 && !Character.isWhitespace(c)) {
                sb.append((char) c);
                c = read();
            }
            return sb.toString();
        }
    }

    static int rankValue(char r) {
        if (r >= '2' && r <= '9') return r - '0';
        switch (r) {
            case 'T': return 10;
            case 'J': return 11;
            case 'Q': return 12;
            case 'K': return 13;
            case 'A': return 14;
        }
        return -1;
    }

    static boolean better(String a, String b, char lead, char trump) {
        char sa = a.charAt(1), sb = b.charAt(1);
        int ra = rankValue(a.charAt(0)), rb = rankValue(b.charAt(0));

        if (sa == sb) return ra > rb;
        if (sa == trump && sb != trump) return true;
        if (sa != trump && sb == trump) return false;
        if (sa == lead && sb != lead) return true;
        return false;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        StringBuilder out = new StringBuilder();

        while (true) {
            String dealerToken = fs.next();
            if (dealerToken == null) break;

            char dealer = dealerToken.charAt(0);
            String trumpToken = fs.next();
            if (trumpToken == null) break;
            char trump = trumpToken.charAt(0);

            String[] cards = new String[52];
            for (int i = 0; i < 52; i++) {
                cards[i] = fs.next();
            }

            // Players in clockwise order: N, E, S, W
            // Teams: N/S and E/W
            int leader;
            switch (dealer) {
                case 'N': leader = 1; break; // left of dealer = E
                case 'E': leader = 2; break; // S
                case 'S': leader = 3; break; // W
                default: leader = 0; break;  // dealer W -> leader N
            }

            int ns = 0, ew = 0;

            for (int trick = 0; trick < 13; trick++) {
                int winner = leader;
                String winCard = cards[trick * 4];
                char leadSuit = winCard.charAt(1);

                for (int j = 1; j < 4; j++) {
                    String cur = cards[trick * 4 + j];
                    if (better(cur, winCard, leadSuit, trump)) {
                        winCard = cur;
                        winner = (leader + j) % 4;
                    }
                }

                if (winner == 0 || winner == 2) ns++;
                else ew++;

                leader = winner;
            }

            if (ns > ew) {
                out.append("NS ").append(ns - 6).append('\n');
            } else {
                out.append("EW ").append(ew - 6).append('\n');
            }
        }

        System.out.print(out.toString());
    }
}

